const GROUP_ID = 'YOUR_VK_GROUP_ID';
const CALLBACK_SECRET = 'YOUR_VK_CALLBACK_SECRET';
const CONFIRMATION_CODE = 'YOUR_VK_CONFIRMATION_CODE';

const body = $input.first().json.body ?? {};

const valid =
  String(body.group_id ?? '') === GROUP_ID &&
  typeof body.secret === 'string' &&
  body.secret === CALLBACK_SECRET;

if (!valid) {
  return [{
    json: {
      accepted: false,
      responseCode: 403,
      responseText: 'forbidden',
    },
  }];
}

if (body.type === 'confirmation') {
  return [{
    json: {
      accepted: true,
      eventType: 'confirmation',
      responseCode: 200,
      responseText: CONFIRMATION_CODE,
    },
  }];
}

return [{
  json: {
    accepted: true,
    eventType: body.type,
    eventId: String(body.event_id ?? ''),
    groupId: String(body.group_id),
    message: body.object?.message ?? null,
    responseCode: 200,
    responseText: 'ok',
  },
}];

const event = $input.first().json;

// Обрабатываем только проверенные входящие сообщения.
if (!event.accepted || event.eventType !== 'message_new') {
  return [];
}

const message = event.message;

if (
  !message ||
  Number(message.out) === 1 ||
  !message.peer_id ||
  !message.from_id
) {
  return [];
}

// Первая версия работает в личной переписке с сообществом.
if (
  Number(message.from_id) <= 0 ||
  Number(message.peer_id) !== Number(message.from_id)
) {
  return [];
}

const question = String(message.text ?? '').trim();
const normalized = question.toLowerCase();

let reply = '';

if (
  ['/start', '/help', 'начать', 'помощь'].includes(normalized)
) {
  reply = [
    'Помогу найти земельные лоты в нашей базе.',
    '',
    'Примеры запросов:',
    'Найди участки под ИЖС в Талдомском округе.',
    'Покажи землю для личного подсобного хозяйства.',
    'Найди участки для аренды в районе Истры.',
    '',
    'Укажите все условия в одном сообщении.',
    'Точную статистику всей базы эта версия не считает.',
  ].join('\n');
} else if (!question) {
  reply = 'Пока я понимаю только текст. Напишите, какой участок вы ищете.';
} else if (question.length > 500) {
  reply = 'Сократите запрос до 500 символов: укажите район, назначение и основные условия.';
}

return [{
  json: {
    peerId: String(message.peer_id),
    userId: String(message.from_id),
    messageId: String(message.id ?? ''),
    conversationMessageId: String(
      message.conversation_message_id ?? ''
    ),
    eventId: event.eventId,
    groupId: event.groupId,
    question,
    needsSearch: reply === '',
    reply,
  },
}];

const data = $input.first().json;
const request = $('Prepare Request').first().json;
let answer;
if (data.error) {
  answer = 'Не удалось выполнить поиск. Попробуйте немного позже.';
} else {
  answer = String(data.reply || data.text || data.output || '').trim();
  if (!answer) answer = 'Не удалось подготовить ответ. Попробуйте уточнить вопрос.';
}
answer = answer.replace(/\*\*([^\n]+?)\*\*/g, '$1');

// Короткие ответы не меняются; длинная карточка передаётся полностью по частям.
// URL и отдельные слова не разрезаются. Оставляем место для номера части.
const chunks = [];
let remaining = answer;
while (remaining.length > (chunks.length ? 2900 : 3000)) {
  const window = remaining.slice(0, 2900);
  let cut = window.lastIndexOf('\n\n');
  if (cut < 1450) cut = window.lastIndexOf('\n');
  if (cut < 1450) {
    const spaces = [...window.matchAll(/\s+/g)];
    cut = spaces.length ? spaces[spaces.length - 1].index : -1;
  }
  if (cut <= 0) throw new Error('В ответе слишком длинная неделимая строка; требуется отдельный документ.');
  chunks.push(remaining.slice(0, cut).trim());
  remaining = remaining.slice(cut).trimStart();
}
if (remaining.trim()) chunks.push(remaining.trim());
if (chunks.length > 30) throw new Error('Карточка превышает 30 сообщений; требуется отдельный документ.');

const eventKey = request.eventId || [request.groupId, request.peerId, request.messageId, request.conversationMessageId].join(':');
function hashKey(key) {
  let hash = 2166136261;
  for (const character of key) hash = Math.imul(hash ^ character.charCodeAt(0), 16777619) >>> 0;
  return (hash % 2147483647) || 1;
}
const used = new Set();
return chunks.map((message, index) => {
  let randomId = hashKey(index === 0 ? eventKey : eventKey + ':part:' + (index + 1));
  while (used.has(randomId)) randomId = randomId % 2147483647 + 1;
  used.add(randomId);
  return {json:{peerId:request.peerId, message:chunks.length>1?'Часть '+(index+1)+' из '+chunks.length+'\n\n'+message:message, randomId}};
});

const results = $input.all();
if (!results.length) throw new Error('VK не вернул результат отправки.');
return results.map((item, index) => {
  const result = item.json;
  if (result.error) {
    const code = result.error.error_code ?? 'unknown';
    throw new Error(`VK не отправил часть ${index + 1}. Код ошибки: ${code}`);
  }
  const messageId = result.response;
  if (!Number.isInteger(messageId) || messageId <= 0) {
    throw new Error(`VK вернул некорректный ID сообщения для части ${index + 1}.`);
  }
  return {json:{sent:true, vkMessageId:messageId}};
});

